function openPageMap(search=""){
  const grouped={};
  PAGE_MANIFEST.forEach(p=>{ const g=routeGroup(p.route); (grouped[g] ||= []).push(p); });
  const body=Object.entries(grouped).map(([group,pages])=>`<section class="page-map-group"><h3>${esc(group)}</h3>${pages.map(p=>`<button class="page-map-link" data-route="${esc(p.route)}" data-search="${esc((routeTitle(p.route)+" "+p.route+" "+p.labels.join(" ")).toLowerCase())}"><div><strong>${esc(routeTitle(p.route))}</strong><br/><code>${esc(p.route)}</code></div><span>${esc(p.component)}</span></button>`).join("")}</section>`).join("");
  const drawer=$("#drawer");
  drawer.innerHTML=`<aside class="drawer-panel"><div class="drawer-header"><div><p class="eyebrow">Complete frontend coverage</p><h2>All 75 project pages</h2><p class="page-subtitle">Routes are taken from the actual frontend router and page/component inventory.</p></div><button class="icon-btn" data-action="close-drawer">×</button></div><input id="page-map-search" class="control page-map-search" placeholder="Search route, page, field or component…" value="${esc(search)}"/>${body}</aside>`;
  drawer.classList.add("open"); drawer.setAttribute("aria-hidden","false");
  filterPageMap(search);
  setTimeout(()=>$("#page-map-search")?.focus(),30);
}
function filterPageMap(value){
  const q=String(value||"").toLowerCase().trim();
  $$(".page-map-link").forEach(el=>el.style.display=!q || el.dataset.search.includes(q)?"grid":"none");
  $$(".page-map-group").forEach(g=>g.style.display=$$(".page-map-link",g).some(x=>x.style.display!=="none")?"block":"none");
}
function closeDrawer(){ $("#drawer").classList.remove("open"); $("#drawer").setAttribute("aria-hidden","true"); }
function openModal(title="Action confirmation",body="This is an interactive wireframe action. No server mutation is performed.",danger=false){
  const modal=$("#modal");
  modal.innerHTML=`<div class="modal-card"><div class="modal-head"><div><p class="eyebrow">Wireframe interaction</p><h2>${esc(title)}</h2></div><button class="icon-btn" data-action="close-modal">×</button></div><div class="modal-body"><p class="page-subtitle" style="margin-top:0">${esc(body)}</p>${field("Reason","textarea","",12)}</div><div class="modal-actions">${btn("Cancel","secondary","close-modal")}${btn(danger?"Confirm reversal":"Confirm","primary","modal-confirm")}</div></div>`;
  modal.classList.add("open"); modal.setAttribute("aria-hidden","false");
}
function closeModal(){ $("#modal").classList.remove("open"); $("#modal").setAttribute("aria-hidden","true"); }
let toastTimer;
function toast(msg){ const el=$("#toast"); el.textContent=msg; el.classList.add("show"); clearTimeout(toastTimer); toastTimer=setTimeout(()=>el.classList.remove("show"),2200); }

function updateLogicVisibility(){
  const route=currentRoute();
  if(route==="/inventory/adjustments"){
    const dir=$("[data-logic-select='direction']")?.value; const cost=$("[data-conditional='in-cost']")?.closest(".field"); if(cost) cost.style.opacity=dir==="IN"?"1":".55";
  }
  if(route==="/expenses/new"){
    const method=$("[data-logic-select='expense-method']")?.value; const c=$("[data-conditional='expense-cash']")?.closest(".field"); const b=$("[data-conditional='expense-bank']")?.closest(".field"); if(c)c.style.display=method==="CASH"?"grid":"none"; if(b)b.style.display=method==="BANK_TRANSFER"?"grid":"none";
  }
  if(route==="/returns/sales/new"){
    const mode=$("[data-logic-select='refund-mode']")?.value; const c=$("[data-conditional='refund-cash']")?.closest(".field"); const b=$("[data-conditional='refund-bank']")?.closest(".field"); if(c)c.style.display=mode==="CASH"?"grid":"none"; if(b)b.style.display=mode==="BANK_TRANSFER"?"grid":"none";
  }
}
function recalcDocument(){
  const editor=$("[data-doc-lines]"); if(!editor) return;
  let subtotal=0;
  $$(".line-editor-row",editor).forEach(row=>{ const q=Number($(".doc-qty",row)?.value||0), r=Number($(".doc-rate",row)?.value||0), d=Number($(".doc-discount",row)?.value||0); const total=Math.max(0,q*r-d); subtotal+=total; const el=$(".doc-line-total",row); if(el)el.textContent=money(total); });
  const disc=Number($("#invoice-discount")?.value||0); const grand=Math.max(0,subtotal-disc); const paid=$$(".payment-amount").reduce((s,x)=>s+Number(x.value||0),0); const due=Math.max(0,grand-paid);
  if($("#doc-subtotal"))$("#doc-subtotal").textContent=money(subtotal); if($("#doc-grand"))$("#doc-grand").textContent=money(grand); if($("#doc-paid"))$("#doc-paid").textContent=money(paid); if($("#doc-due"))$("#doc-due").textContent=money(due);
}
function addPaymentRow(){
  const editor=$("[data-payment-editor]"); if(!editor) return;
  const toolbar=$(".editor-toolbar",editor); const row=document.createElement("div"); row.className="line-editor-row cols-payment"; row.innerHTML=`<select class="control payment-method" data-action="payment-method"><option value="CASH">Cash</option><option value="BANK_TRANSFER">Bank transfer</option></select><select class="control payment-account"><option>Main Counter Cash</option><option>Petty Cash</option></select><input class="control payment-amount" type="number" value="0"/><button class="remove-row" data-action="remove-row">×</button>`; editor.insertBefore(row,toolbar); recalcDocument();
}
function paymentMethodChanged(select){
  const row=select.closest(".line-editor-row"); const account=$(".payment-account",row); if(!account)return; account.innerHTML=select.value==="CASH"?DEMO.cashAccounts.map(x=>`<option>${esc(x)}</option>`).join(""):DEMO.bankAccounts.map(x=>`<option>${esc(x)}</option>`).join("");
}
function render(){
  const route=currentRoute(); const isLogin=route==="/login";
  document.body.classList.toggle("auth-mode",isLogin);
  if(!isLogin){ renderSidebar(route); renderTopbar(route); }
  $("#app").innerHTML=renderPage(route);
  document.title=`${routeTitle(route)} — Wholesale ERP Wireframe`;
  updateLogicVisibility(); recalcDocument();
  window.scrollTo(0, 0);
}

window.addEventListener("hashchange",()=>{ closeDrawer(); closeModal(); document.body.classList.remove("nav-open"); render(); });
document.addEventListener("input",e=>{
  if(e.target.id==="page-map-search") filterPageMap(e.target.value);
  if(e.target.matches(".doc-qty,.doc-rate,.doc-discount,#invoice-discount,.payment-amount")) recalcDocument();
});
document.addEventListener("change",e=>{
  if(e.target.matches("[data-logic-select]")) updateLogicVisibility();
  if(e.target.matches(".payment-method")) paymentMethodChanged(e.target);
});
document.addEventListener("click",e=>{
  const routeEl=e.target.closest("[data-route]");
  if(routeEl){ e.preventDefault(); navigate(routeEl.dataset.route); return; }
  const actionEl=e.target.closest("[data-action]"); if(!actionEl)return;
  const a=actionEl.dataset.action;
  if(a==="route"){ navigate(actionEl.dataset.route||"/dashboard"); return; }
  if(a==="page-map"){ openPageMap(); return; }
  if(a==="close-drawer"){ closeDrawer(); return; }
  if(a==="close-modal"){ closeModal(); return; }
  if(a==="mobile-nav"){ document.body.classList.toggle("nav-open"); return; }
  if(a==="global-search"){ openPageMap(actionEl.value||""); return; }
  if(a==="remove-row"){ actionEl.closest(".line-editor-row")?.remove(); recalcDocument(); toast("Line removed from wireframe."); return; }
  if(a==="add-payment-row"){ addPaymentRow(); return; }
  if(a==="payment-method"){ return; }
  if(a==="modal" || a==="confirm"){ openModal(a==="confirm"?"Confirm financial action":"Edit / review action","This wireframe models the production confirmation step. Confirmed financial records are immutable and corrections use linked reversing/return transactions.",a==="confirm"); return; }
  if(a==="modal-confirm"){ closeModal(); toast("Wireframe action confirmed — no data was sent."); return; }
  if(a==="login"){ toast("Demo sign-in successful."); setTimeout(()=>navigate("/dashboard"),350); return; }
  if(a==="password"){ toast("Password validation shown; all sessions would be revoked."); return; }
  if(a==="session"){ toast("Session would be revoked immediately."); return; }
  if(a==="filter"){ toast("Filters applied to sample data."); return; }
  if(a==="clear"){ $$('input, select').forEach(x=>{ if(x.type!=="date"&&x.type!=="checkbox")x.value=""; if(x.type==="checkbox")x.checked=false; }); toast("Wireframe filters cleared."); return; }
  if(a==="save"){ toast("Draft/master-data save represented."); return; }
  if(a==="doc-confirm" || a==="payment-confirm"){ openModal("Confirm transaction","In production this action validates business rules, requires idempotency where applicable, then commits every stock / ledger / payment effect in one database transaction."); return; }
  if(a==="validate-import"){ toast("94 rows validated — 92 valid, 2 require correction."); return; }
  if(a==="download" || a==="print"){ toast(a==="download"?"File generation/download represented.":"Print layout would open here."); return; }
  if(a==="refresh"){ toast("Dashboard sample data refreshed."); return; }
  if(a==="page"){ toast("Pagination interaction represented."); return; }
  if(a==="add-row" || a==="add-doc-row"){ toast("Additional row interaction represented in this wireframe."); return; }
  toast("Interactive wireframe control.");
});

if(!location.hash) location.hash="#/dashboard";
try {
  render();
} catch (error) {
  console.error("Wireframe failed to render", error);
  const app = document.getElementById("app");
  if (app) {
    app.innerHTML = `<div style="padding:32px;font-family:system-ui,sans-serif"><h1>Wireframe loading error</h1><p>Please open this file in a modern browser. Error: ${esc(error?.message || error)}</p></div>`;
  }
}
